def batches_to_the_default_store(apps, schema_editor):
    """Every batch so far is in the default shop (Khan Perfume). The opening
    split to Scentory is a separate, previewed step: split_opening_stock."""
    Store = apps.get_model('stock', 'Store')
    Purchase = apps.get_model('stock', 'Purchase')
    default = Store.objects.filter(is_default=True).first() or Store.objects.order_by('id').first()
    if default is not None:
        Purchase.objects.filter(store__isnull=True).update(store=default)
    # both shops keep an opened sample of every product
    Store.objects.update(keeps_samples=True)


